// SERVER-ONLY. Per-question media credits ("Nguồn tư liệu"), generated by
// scripts/media/attribution.mjs from the production manifests and media/sources.json.
// A question's entries are sent to clients only inside its RoundReveal, i.e. after the server has
// closed that round; other questions' credits are never included. Never import from client code.
import { readFileSync } from 'node:fs';
import type { RoundAttribution } from '../../shared/protocol';

interface AttributionFile {
  questions: Record<string, RoundAttribution>;
}

const data = JSON.parse(readFileSync(new URL('./attribution.json', import.meta.url), 'utf8')) as AttributionFile;

/** Credits for one production question id (e.g. 'q3'). Throws if the generated file lacks it. */
export function attributionFor(questionId: string): RoundAttribution {
  const a = data.questions[questionId];
  if (!a) throw new Error(`no attribution for ${questionId} — run node --import tsx scripts/media/attribution.mjs`);
  return a;
}
